/*
 * A183081  Tree generated by the Beatty sequence of 4-sqrt(5).
 * https://oeis.org/A183081
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 106, u32 n <= 7737, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = Tree‐array value T(d,p) where
 * d = ⌊log₂(n − 1)⌋ + 1 (depth level, d = 0 for n = 1, d = 1 for n = 2),
 * p = n − 1 − (2⁺ʰⁱʳʹᴰ − 1) (position within level d),
 * and children are taken using L(x)=⌊x·(4−√5)⌋ and
 *                     U(x)=⌊x·(4+√5)/4⌋.
 * A recurrence for L and U is
 *    L(x) = 4·x − ⌊x√5⌋ − 1
 *    U(x) = (7·x + ⌊x√5⌋)/4
 * where ⌊x√5⌋ is computed as ⌊√(5·x²)⌋ via integer square root.
 */
#include <stdint.h>
#include "../utils/floor_sqrt.h"

/* Return ⌊n·√5⌋ using integer arithmetic: ⌊√(5·n²)⌋ */
static inline seq_t floor_n_sqrt5(idx_t n)
{
    /* product is at most 5·n²; for n up to ~10⁴ it fits in 64‑bit. */
    __uint128_t prod = (__uint128_t)n * n * 5;
    return floor_sqrt((seq_t)prod);
}

/* Beatty sequence floor(n·(4−√5)) */
static inline seq_t L(seq_t n)
{
    seq_t sq5n = floor_n_sqrt5((idx_t)n);
    /* L(n) = 4n − ceil(n√5) = 4n − (sq5n + 1) */
    return (seq_t)4 * n - sq5n - 1;
}

/* Beatty sequence floor(n·(4+√5)/4) */
static inline seq_t U(seq_t n)
{
    seq_t sq5n = floor_n_sqrt5((idx_t)n);
    /* U(n) = ⌊(7n + ⌊n√5⌋)/4⌋  (no carry from fractional part) */
    return ((seq_t)7 * n + sq5n) / 4;
}

seq_t a(idx_t n)
{
    if (n == 1U) return (seq_t)1;
    if (n == 2U) return (seq_t)2;

    /* n≥3 : compute depth and path in the binary tree */
    idx_t idx = n - 1;                 /* zero‑based index */
    /* Highest power of two ≤ idx (idx > 0 here) */
    int bit = 63 - __builtin_clzll(idx); /* floor(log₂(idx)) */
    idx_t start = (idx_t)1 << bit;         /* start index of this depth */
    int depth = bit + 1;                   /* d = log₂(start) + 1 */
    idx_t pos   = idx - start;             /* position within the depth */

    seq_t value = (seq_t)2;                /* node at depth 1 */
    /* Walk depth‑1 decisions (most significant bit first) */
    for (int i = depth - 2; i >= 0; --i) {
        if (pos & ((idx_t)1 << i))
            value = U(value);             /* right child */
        else
            value = L(value);             /* left child  */
    }
    return value;
}
